from solution import dig_let


def test_issue_python_example():
    """Example assert dig_let("python")==(6,0)."""
    assert dig_let("python") == (6, 0)  # 6 letters: 1+1+1+1+1+1=6; 0 digits


def test_issue_empty_string():
    """Rule: calculate the number of digits and letters in a string."""
    assert dig_let("") == (0, 0)  # 0 letters; 0 digits


def test_issue_single_letter():
    """Rule: calculate the number of digits and letters in a string."""
    assert dig_let("a") == (1, 0)  # 1 letter: 1=1; 0 digits


def test_issue_single_digit():
    """Rule: calculate the number of digits and letters in a string."""
    assert dig_let("5") == (0, 1)  # 0 letters; 1 digit: 1=1


def test_issue_digits_only():
    """Rule: calculate the number of digits and letters in a string."""
    assert dig_let("12345") == (0, 5)  # 0 letters; 5 digits: 1+1+1+1+1=5


def test_issue_uppercase_letters():
    """Rule: calculate the number of digits and letters in a string."""
    assert dig_let("ABC") == (3, 0)  # 3 letters: 1+1+1=3; 0 digits


def test_issue_mixed_letters_digits():
    """Rule: calculate the number of digits and letters in a string."""
    assert dig_let("abc123") == (3, 3)  # 3 letters: 1+1+1=3; 3 digits: 1+1+1=3


def test_issue_ignores_spaces():
    """Rule: calculate the number of digits and letters in a string."""
    assert dig_let("a b 1") == (2, 1)  # 2 letters: 1+1=2; 1 digit: 1=1; 2 spaces ignored


def test_issue_ignores_punctuation():
    """Rule: calculate the number of digits and letters in a string."""
    assert dig_let("a1!?") == (1, 1)  # 1 letter: 1=1; 1 digit: 1=1; 2 symbols ignored


def test_issue_symbols_only_zero():
    """Rule: calculate the number of digits and letters in a string."""
    assert dig_let("!? ") == (0, 0)  # 0 letters; 0 digits; 3 symbols ignored


def test_contract_returns_tuple_pair():
    """Rule: function calculates counts as shown in example tuple (6,0)."""
    result = dig_let("ab12")  # 2 letters: 1+1=2; 2 digits: 1+1=2
    assert isinstance(result, tuple) and len(result) == 2  # pair as in (6, 0)


def test_contract_takes_single_string():
    """Rule: dig_let(s) takes a string s."""
    assert dig_let("a") == (1, 0)  # 1 letter: 1=1; 0 digits; called with one string arg
